const allRows = $input.all().map(item => item.json);
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const thisWeek = allRows.filter(r => {
  const d = new Date(r.date);
  return !isNaN(d) && d >= weekAgo && d <= now;
});

const strong = thisWeek.filter(r => r.recommendation === 'Strong Match');
const possible = thisWeek.filter(r => r.recommendation === 'Possible Match');
const notMatch = thisWeek.filter(r => r.recommendation === 'Not a Match');
const interviewsScheduled = thisWeek.filter(r => r.interview_status === 'Scheduled');
const schedulingConflicts = thisWeek.filter(r => r.interview_status === 'Pending Manual Review - No Available Slot Found' || r.interview_status === 'Pending Manual Review - Scheduling Race Lost');
const duplicateApplications = thisWeek.filter(r => r.interview_status === 'Duplicate Application - Not Reprocessed');
const invalidSubmissions = thisWeek.filter(r => (r.interview_status || '').startsWith('Rejected - Submission Invalid'));

const pendingReview = allRows
  .filter(r => (r.interview_status || '').startsWith('Pending Manual Review') || (r.interview_status || '').startsWith('Needs Manual Review'))
  .sort((a, b) => (parseFloat(b.match_score) || 0) - (parseFloat(a.match_score) || 0))
  .slice(0, 5);

function escapeHtml(s) {
  return (s === undefined || s === null ? '' : String(s))
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

let html = '<div style="font-family: Arial, sans-serif; color: #222;">';
html += '<h2>AI Recruiting Weekly Report</h2>';
html += '<h3>Summary</h3>';
html += '<ul>';
html += '<li><b>Total Applications:</b> ' + thisWeek.length + '</li>';
html += '<li><b>Strong Matches:</b> ' + strong.length + '</li>';
html += '<li><b>Possible Matches:</b> ' + possible.length + '</li>';
html += '<li><b>Not a Match:</b> ' + notMatch.length + '</li>';
html += '<li><b>Pending Review (new this week):</b> ' + thisWeek.filter(r => (r.interview_status || '').startsWith('Pending Manual Review') || (r.interview_status || '').startsWith('Needs Manual Review')).length + '</li>';
html += '<li><b>Interviews Scheduled:</b> ' + interviewsScheduled.length + '</li>';
html += '<li><b>Scheduling Conflicts:</b> ' + schedulingConflicts.length + '</li>';
html += '<li><b>Duplicate Applications:</b> ' + duplicateApplications.length + '</li>';
if (invalidSubmissions.length > 0) {
  html += '<li><b>Invalid Submissions (rejected before scoring):</b> ' + invalidSubmissions.length + '</li>';
}
html += '</ul>';

if (interviewsScheduled.length > 0) {
  html += '<h3>Interviews Scheduled This Week</h3>';
  html += '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse: collapse;"><tr><th>Name</th><th>Position</th><th>Score</th><th>Details</th></tr>';
  for (const c of interviewsScheduled) {
    html += '<tr><td>' + escapeHtml(c.full_name) + '</td><td>' + escapeHtml(c.position) + '</td><td>' + escapeHtml(c.match_score) + '</td><td>' + escapeHtml(c.notes) + '</td></tr>';
  }
  html += '</table>';
}

html += '<h3>Top Candidates Currently Awaiting Manual Review</h3>';
html += '<p style="font-size: 0.9em; color: #555;">(Full outstanding backlog, not limited to this week - top 5 by score)</p>';
if (pendingReview.length === 0) {
  html += '<p>No candidates currently pending manual review.</p>';
} else {
  html += '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse: collapse;"><tr><th>Name</th><th>Position</th><th>Status</th><th>Score</th><th>Notes</th></tr>';
  for (const c of pendingReview) {
    html += '<tr><td>' + escapeHtml(c.full_name) + '</td><td>' + escapeHtml(c.position) + '</td><td>' + escapeHtml(c.interview_status) + '</td><td>' + escapeHtml(c.match_score) + '</td><td>' + escapeHtml(c.notes) + '</td></tr>';
  }
  html += '</table>';
}
html += '</div>';

return [{
  json: {
    html_report: html,
    total_this_week: thisWeek.length,
    strong_count: strong.length,
    possible_count: possible.length,
    not_match_count: notMatch.length,
    interviews_scheduled_count: interviewsScheduled.length,
    scheduling_conflicts_count: schedulingConflicts.length,
    duplicate_applications_count: duplicateApplications.length,
    invalid_submissions_count: invalidSubmissions.length,
    pending_review_backlog_count: pendingReview.length
  }
}];
